import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.D3fmyz3M.js";const u=JSON.parse('{"title":"版本兼容性矩阵","description":"本教程锁定的依赖版本、浏览器支持与常见组合的兼容性结论。","frontmatter":{"title":"版本兼容性矩阵","description":"本教程锁定的依赖版本、浏览器支持与常见组合的兼容性结论。"},"headers":[],"relativePath":"appendix/compatibility.md","filePath":"appendix/compatibility.md","lastUpdated":1792674288000}'),a={name:"appendix/compatibility.md"};function i(c,t,n,l,h,s){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="版本兼容性矩阵" tabindex="-1">版本兼容性矩阵 <a class="header-anchor" href="#版本兼容性矩阵" aria-label="Permalink to &quot;版本兼容性矩阵&quot;">​</a></h1><p>教程中的示例全部锁定版本，避免&quot;昨天还能跑，今天装完就报错&quot;。下表与仓库中的 <code>package.json</code> 保持一致。</p><h2 id="运行时与工具链" tabindex="-1">运行时与工具链 <a class="header-anchor" href="#运行时与工具链" aria-label="Permalink to &quot;运行时与工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>版本</th><th>说明</th></tr></thead><tbody><tr><td>Node.js</td><td><code>&gt;= 22.13.0</code></td><td>建议 22 LTS 或 24</td></tr><tr><td>pnpm</td><td><code>12.10.1</code></td><td>通过 <code>packageManager</code> 字段锁定</td></tr><tr><td>Vite</td><td><code>5.4.21</code></td><td>所有示例统一</td></tr><tr><td>Vue</td><td><code>3.5.44</code></td><td>宿主与 Vue 子应用统一</td></tr><tr><td>React / React DOM</td><td><code>18.3.1</code></td><td>single-spa、qiankun、micro-app、wujie 的 React 子应用</td></tr><tr><td>VitePress</td><td><code>1.6.4</code></td><td>文档站</td></tr><tr><td><code>@vitejs/plugin-vue</code></td><td><code>5.2.4</code></td><td>与 Vite 5 匹配</td></tr><tr><td>concurrently</td><td><code>10.0.6</code></td><td>多应用并行启动</td></tr></tbody></table><h2 id="微前端框架" tabindex="-1">微前端框架 <a class="header-anchor" href="#微前端框架" aria-label="Permalink to &quot;微前端框架&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>版本</th><th>接入方式</th><th>子应用改造</th></tr></thead><tbody><tr><td>iframe</td><td>浏览器原生</td><td><code>&lt;iframe src&gt;</code></td><td>无</td></tr><tr><td>Web Components</td><td>浏览器原生</td><td><code>defineCustomElement</code></td><td>导出组件并注册标签</td></tr><tr><td>single-spa</td><td><code>6.0.3</code></td><td><code>registerApplication</code></td><td>导出生命周期</td></tr><tr><td>qiankun</td><td><code>2.10.16</code></td><td><code>registerMicroApps</code></td><td>UMD + 生命周期</td></tr><tr><td>micro-app</td><td><code>1.0.0-rc.32</code></td><td><code>&lt;micro-app&gt;</code> 标签</td><td>原则上无需改造</td></tr><tr><td>wujie</td><td><code>2.1.0</code></td><td><code>startApp</code></td><td>原则上无需改造</td></tr><tr><td>Module Federation</td><td><code>@originjs/vite-plugin-federation@1.4.1</code></td><td><code>federation()</code> 插件</td><td>暴露模块</td></tr></tbody></table><blockquote><p>micro-app 的 <code>1.0.0-rc.32</code> 是 1.x 预发布版本。生产接入前请确认团队能接受预发布版本，或锁定到当时的最新稳定版并做回归。</p></blockquote><h2 id="框架与构建组合" tabindex="-1">框架与构建组合 <a class="header-anchor" href="#框架与构建组合" aria-label="Permalink to &quot;框架与构建组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宿主</th><th>子应用</th><th>结论</th><th>备注</th></tr></thead><tbody><tr><td>Vue 3 + Vite</td><td>Vue 3 + Vite</td><td>支持</td><td>所有运行时方案均可</td></tr><tr><td>Vue 3 + Vite</td><td>React 18 + Vite</td><td>支持</td><td>single-spa / qiankun / micro-app / wujie 已验证</td></tr><tr><td>Vue 3 + Vite</td><td>Vue 3 + Vite（MF remote）</td><td>支持</td><td><code>shared.vue</code> 必须 <code>singleton</code></td></tr><tr><td>Vue 3 + Vite</td><td>React（MF remote）</td><td>需额外桥接</td><td>宿主无法直接渲染 React 组件，建议统一技术栈或改为 Web Component 包装</td></tr><tr><td>Vue 3 + Vite</td><td>Vue 3 + Webpack（qiankun）</td><td>支持</td><td>qiankun 生态的典型组合</td></tr><tr><td>Vue 3 + Vite</td><td>Vue 3 + Vite（qiankun）</td><td>需构建改造</td><td>库模式 UMD + 固定产物名</td></tr><tr><td>React 18 + Vite</td><td>Vue 3 + Vite</td><td>支持</td><td>运行时方案不限制子应用框架</td></tr><tr><td>任意</td><td>任意（iframe）</td><td>支持</td><td>无框架约束</td></tr></tbody></table><h2 id="浏览器支持" tabindex="-1">浏览器支持 <a class="header-anchor" href="#浏览器支持" aria-label="Permalink to &quot;浏览器支持&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>Chrome</th><th>Edge</th><th>Firefox</th><th>Safari</th><th>说明</th></tr></thead><tbody><tr><td>iframe + <code>postMessage</code></td><td>全版本</td><td>全版本</td><td>全版本</td><td>全版本</td><td>基线方案</td></tr><tr><td>Custom Elements v1</td><td>54+</td><td>79+</td><td>63+</td><td>10.1+</td><td>Web Components 必需</td></tr><tr><td>Shadow DOM v1</td><td>53+</td><td>79+</td><td>63+</td><td>10+</td><td>样式隔离必需</td></tr><tr><td>ES Modules</td><td>61+</td><td>79+</td><td>67+</td><td>11+</td><td>micro-app <code>esmodule</code>、MF 必需</td></tr><tr><td><code>Proxy</code></td><td>49+</td><td>79+</td><td>18+</td><td>10+</td><td>qiankun / micro-app 沙箱必需</td></tr><tr><td><code>import()</code> 动态导入</td><td>63+</td><td>79+</td><td>67+</td><td>11.1+</td><td>MF 与按需加载</td></tr><tr><td><code>structuredClone</code></td><td>98+</td><td>98+</td><td>94+</td><td>15.4+</td><td>部分方案内部使用，需 polyfill 时注意</td></tr></tbody></table><blockquote><p>若需要支持 IE，只有 iframe 方案可选。其余方案均依赖 <code>Proxy</code>、<code>Custom Elements</code> 或 ES Modules。</p></blockquote><h2 id="端口分配" tabindex="-1">端口分配 <a class="header-anchor" href="#端口分配" aria-label="Permalink to &quot;端口分配&quot;">​</a></h2><p>示例按方案递增分配端口，避免冲突：</p><table tabindex="0"><thead><tr><th>方案</th><th>主应用</th><th>子应用 A</th><th>子应用 B</th></tr></thead><tbody><tr><td>iframe</td><td>5173</td><td>5174</td><td>—</td></tr><tr><td>Web Components</td><td>5175</td><td>5176</td><td>—</td></tr><tr><td>single-spa</td><td>5177</td><td>5178</td><td>5179</td></tr><tr><td>qiankun</td><td>5180</td><td>5181</td><td>5182</td></tr><tr><td>micro-app</td><td>5183</td><td>5184</td><td>5185</td></tr><tr><td>wujie</td><td>5186</td><td>5187</td><td>5188</td></tr><tr><td>Module Federation</td><td>5189</td><td>5190</td><td>5191</td></tr></tbody></table><h2 id="升级注意事项" tabindex="-1">升级注意事项 <a class="header-anchor" href="#升级注意事项" aria-label="Permalink to &quot;升级注意事项&quot;">​</a></h2><ul><li><strong>Vite 6 / 7</strong>：本项目未验证。升级前重点检查 <code>@originjs/vite-plugin-federation</code> 与 qiankun 子应用的库模式构建。</li><li><strong>Vue 3.6+</strong>：Vapor 模式与 <code>defineCustomElement</code> 的行为可能有差异，Web Components 示例需回归。</li><li><strong>React 19</strong>：<code>createRoot</code> 用法不变，但 <code>react-dom</code> 的导出有调整，single-spa 示例中的挂载代码需确认。</li><li><strong>qiankun 3.x</strong>：若采用，需重新验证沙箱与样式隔离配置，API 有变化。</li></ul><p>升级原则：先升子应用，再升宿主；每次只升一个方案，跑通该方案的示例再继续。</p>',18)])])}const m=d(a,[["render",i]]);export{u as __pageData,m as default};
